// CSD_RATIONALE_BEGIN
// This strategy tracks the visible output (`generated`), whether generation is
// currently inside an arithmetic-computation span, and the active constrained
// span contents (`currentConstrainedOut`). Outside spans it mostly generates
// freely, but it also watches recent tokens and punctuation-like cues common in
// step-by-step math solutions; after such cues it may proactively open a `<<`
// span so arithmetic can be produced under parser control. Inside spans it uses
// parser-guided decoding with soft preferences from `validTokenGroups`, mild
// repetition avoidance, and occasional bounded multi-token symbol steps when
// the parser state is wide. This supports the task by making arithmetic text
// appear inside visible delimiters while preserving parser-valid constrained
// content throughout active spans.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the outside-span chunk branch, `insideConstrainedOut`
//   stays false unless `UnconstrainedChunk` already emitted `<<`; then
//   `EnterObservedConstrainedSpan` sets `currentConstrainedOut := []`, which is
//   valid by the precondition `parser.IsValidPrefix([])`. In the proactive-open
//   branch, `OpenConstrainedSpan` likewise enters with empty constrained state,
//   so the invariant holds. In the close branch, `CloseConstrainedSpan` exits
//   constrained mode, making the implication vacuous. In the repair branch,
//   `RollbackConstrainedSuffix` returns a parser-valid constrained prefix. In
//   the one-token constrained branches, the chosen token is produced by a
//   helper whose contract preserves parser validity (or EOS, which breaks), and
//   `AppendConstrainedToken` commits that valid extension. In the symbol branch,
//   `ConstrainedSymbolInGenerated` returns a valid constrained prefix directly.
// progress: The outside chunk branch increases `steps` by `stepsUsed`, and the
//   helper appends at most that many visible tokens, so
//   `|generated| <= |generatedPrefix| + steps` is preserved. The proactive-open
//   and close branches each consume one token-step and append at most one
//   visible delimiter. The repair branch does not increase visible output and
//   still increments `steps` by 1, so the bound remains true. The one-token
//   constrained branches consume exactly one token-step; they append at most one
//   visible token, and EOS may consume a step without visible growth. The
//   symbol branch consumes `stepsUsed` token-steps and may accept only a prefix
//   of what was sampled, so visible growth is at most the consumed budget;
//   therefore the output-length bound is preserved there as well.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var triggerArmed: bool := false;
var rollbackLimit: nat := 32;
var narrowThreshold: nat := 10;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if triggerArmed {
      var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
      generated := openedGenerated;
      insideConstrainedOut := openedInside;
      currentConstrainedOut := openedCurrent;
      triggerArmed := false;
      steps := steps + 1;
    } else {
      var remainingChunk: nat := maxSteps - steps;
      var chunkBudget: nat := if remainingChunk > 3 then 3 else remainingChunk;
      var chunkedGenerated, stoppedOnOpenSpan, stoppedOnEos, stepsUsed := helpers.UnconstrainedChunk(
        lm, prompt, generated, chunkBudget, "<<", eosToken
      );
      generated := chunkedGenerated;
      steps := steps + stepsUsed;
      if stoppedOnEos {
        break;
      } else if stoppedOnOpenSpan {
        var enteredGenerated, enteredInside, enteredCurrent := helpers.EnterObservedConstrainedSpan(lm, generated);
        generated := enteredGenerated;
        insideConstrainedOut := enteredInside;
        currentConstrainedOut := enteredCurrent;
        triggerArmed := false;
      } else {
        var prevEq, foundEq := helpers.LastTokenBefore(generated, "=");
        var prevColon, foundColon := helpers.LastTokenBefore(generated, ":");
        var sinceEq := helpers.TokensSinceLastOccurrence(generated, "=");
        var sinceColon := helpers.TokensSinceLastOccurrence(generated, ":");
        if foundEq || foundColon || sinceEq <= 2 || sinceColon <= 2 {
          triggerArmed := true;
        } else {
          triggerArmed := false;
        }
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    triggerArmed := false;
    steps := steps + 1;
  } else if |currentConstrainedOut| >= rollbackLimit {
    var rolledGenerated, rolledCurrent := helpers.RollbackConstrainedSuffix(
      parser, generated, currentConstrainedOut
    );
    generated := rolledGenerated;
    insideConstrainedOut := true;
    currentConstrainedOut := rolledCurrent;
    steps := steps + 1;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);

    if stepTokenBudget > 1 && validCount > narrowThreshold {
      var remaining: nat := maxSteps - steps;
      var symbolBudget: nat := if stepTokenBudget > remaining then remaining else stepTokenBudget;
      var symbolGenerated, symbolCurrent, hitEos, stepsUsed := helpers.ConstrainedSymbolInGenerated(
        lm, parser, constrainedPrompt, generated, currentConstrainedOut, symbolBudget, eosToken
      );
      generated := symbolGenerated;
      insideConstrainedOut := true;
      currentConstrainedOut := symbolCurrent;
      steps := steps + stepsUsed;
      if hitEos {
        break;
      }
    } else {
      var next := eosToken;
      if helpers.DeadEndDetection(parser, currentConstrainedOut, 2) {
        next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
      } else if |currentConstrainedOut| < 2 {
        next := helpers.SafePenalizedConstrainedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, [">>"], 6.0, eosToken
        );
      } else if helpers.CountTokenOccurrences(generated, "<<") > helpers.CountTokenOccurrences(generated, ">>") {
        next := helpers.SafeRepetitionPenaltyStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, generated, 2.0, eosToken
        );
      } else if validCount <= narrowThreshold {
        next := helpers.AdaptiveConstrainedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
        );
      } else {
        next := helpers.GroupBoostedConstrainedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, eosToken
        );
      }

      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := appendedGenerated;
        insideConstrainedOut := appendedInside;
        currentConstrainedOut := appendedCurrent;
      }
    }
  }
}

cost := steps;

